import * as React from "react"
import { StaticImage } from "gatsby-plugin-image"
import { HardHat } from "./Icons"
import * as s from "./SitePreview.module.css"

const NAV = ["Home", "Services", "About", "Contact"]

/**
 * The mock contractor website shown inside a laptop.  Everything inside is
 * em-based, so the `--mock-size` custom property set by the consuming class
 * resizes the whole thing at once (the mock is always 34em wide).
 */
const SitePreview = ({
  name = "YOURDOMAIN",
  title = "Reliable Contracting for a Stronger Tomorrow.",
  sub,
  className = "",
}) => (
  <div className={`${s.laptop} ${className}`} aria-hidden="true">
    <div className={s.lid}>
      <div className={s.screen}>
        <div className={s.topbar}>
          <HardHat className={s.topbarMark} />
          <span className={s.topbarName}>{name}</span>
          <nav className={s.topbarNav}>
            {NAV.map(item => (
              <span key={item}>{item}</span>
            ))}
          </nav>
        </div>

        <div className={s.hero}>
          <div className={s.heroImg}>
            <StaticImage
              src="../images/site-hero-house.jpg"
              alt=""
              placeholder="blurred"
              layout="fullWidth"
              quality={72}
            />
          </div>
          <div className={s.heroScrim} />
          <div className={s.heroCopy}>
            <div className={s.heroTitle}>{title}</div>
            {sub && <div className={s.heroSub}>{sub}</div>}
            <span className={s.heroBtn}>Get a Free Quote</span>
          </div>
        </div>

        <div className={s.thumbs}>
          <div>
            <StaticImage src="../images/site-thumb-kitchen.jpg" alt="" placeholder="blurred" width={220} quality={70} />
          </div>
          <div>
            <StaticImage src="../images/site-thumb-roofing.jpg" alt="" placeholder="blurred" width={220} quality={70} />
          </div>
          <div>
            <StaticImage src="../images/site-thumb-bathroom.jpg" alt="" placeholder="blurred" width={220} quality={70} />
          </div>
        </div>
      </div>
    </div>
    <div className={s.base} />
  </div>
)

export default SitePreview
